#!/usr/bin/env node
// KTX2 (Basis Universal) copy of a character GLB for the engine (checkpoint-1 §2 item 8):
//   node web/tools/ktx2.mjs IN.glb OUT.glb [--uastc-quality 2] [--etc1s-quality 128]
// UASTC (quality 2, Zstandard) for normals, ORM / roughness / occlusion, clearcoat and anisotropy maps;
// ETC1S (quality 128, sRGB transfer) for base colour and sheen colour; mipmaps generated by the
// encoder. Blender cannot import KTX2, so the PNG GLB stays the build's source of truth and this writes
// a separate file (export.ktx2 names it character.ktx2.glb). Encoder: ktx2-encoder (basis_universal
// WASM, no toktx needed); glTF I/O: @gltf-transform/core. Writes only OUT.
import { readFile, writeFile } from 'node:fs/promises';
import { NodeIO } from '@gltf-transform/core';
import { ALL_EXTENSIONS } from '@gltf-transform/extensions';
import { ktx2 } from 'ktx2-encoder/gltf-transform';
import { PNG } from 'pngjs';

const argv = process.argv.slice(2);
const [src, dst] = argv.filter((a) => !a.startsWith('--') && !/^\d+$/.test(a));
const opt = (n, d) => {
  const i = argv.indexOf(`--${n}`);
  return i >= 0 ? Number(argv[i + 1]) : d;
};
if (!src || !dst) {
  console.error('usage: ktx2.mjs IN.glb OUT.glb [--uastc-quality 2] [--etc1s-quality 128]');
  process.exit(2);
}
const uastcQ = opt('uastc-quality', 2);
const etc1sQ = opt('etc1s-quality', 128);

// LDR images are decoded here (the encoder needs RGBA rows in Node); JPEG does not occur in our GLBs
async function imageDecoder(buf) {
  const png = PNG.sync.read(Buffer.from(buf));
  return { width: png.width, height: png.height, data: new Uint8Array(png.data.buffer, png.data.byteOffset, png.data.length) };
}

const t0 = Date.now();
const io = new NodeIO().registerExtensions(ALL_EXTENSIONS);
const doc = await io.readBinary(new Uint8Array(await readFile(src)));
const before = doc.getRoot().listTextures().reduce((n, t) => n + (t.getImage()?.byteLength ?? 0), 0);
const common = { generateMipmap: true, imageDecoder };
await doc.transform(
  ktx2({ ...common, isUASTC: true, uastcLDRQualityLevel: uastcQ, needSupercompression: true, isNormalMap: true, slots: /^normalTexture$/ }),
  ktx2({ ...common, isUASTC: true, uastcLDRQualityLevel: uastcQ, needSupercompression: true, slots: /(occlusion|metallicRoughness|clearcoat|clearcoatRoughness|anisotropy)Texture$/ }),
  ktx2({ ...common, isUASTC: false, qualityLevel: etc1sQ, isSetKTX2SRGBTransferFunc: true, slots: /^(baseColor|sheenColor|emissive)Texture$/ }),
);
const texs = doc.getRoot().listTextures();
const after = texs.reduce((n, t) => n + (t.getImage()?.byteLength ?? 0), 0);
const left = texs.filter((t) => t.getMimeType() !== 'image/ktx2').map((t) => t.getName());
await writeFile(dst, await io.writeBinary(doc));
console.log(JSON.stringify({ in: src, out: dst, textures: texs.length, png_left: left, image_mb_before: +(before / 1e6).toFixed(1), image_mb_after: +(after / 1e6).toFixed(1), uastc_quality: uastcQ, etc1s_quality: etc1sQ, seconds: Math.round((Date.now() - t0) / 1000) }));
